(function(root){
'use strict';
const $=q=>document.querySelector(q),escape=x=>String(x??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const colors={'6005':'#114232','6001':'#287233','5010':'#0e4c92','9005':'#0a0a0a','9010':'#f1ece1','9016':'#f6f6f6','7016':'#383e42','7035':'#c5c7c4','3000':'#af2b1e','1023':'#f9a800','7024':'#45494e','8014':'#49392d','7032':'#b8b799'};
let q='',sort='name',reverse=false,ralFilter='',workFilter='',stockFilter='';
const state=()=>root.EngefexPaintState();
const list=()=>state().paintStock||[];
const n=x=>Number(String(x??0).replace(',','.'))||0;
const ral=x=>x.ral||((x.name||'').match(/\bRAL\s*(\d{4})/i)||[])[1]||'';
const amount=x=>n(x).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const works=x=>(x.works||[]).join('; ');
const refresh=()=>root.EngefexPaintRefresh();
function rows(){let a=[...list()].filter(x=>[x.id,x.name,x.description,ral(x),works(x)].join(' ').toLowerCase().includes(q.toLowerCase())).filter(x=>!ralFilter||ral(x)===ralFilter).filter(x=>!workFilter||(x.works||[]).includes(workFilter)).filter(x=>!stockFilter||(stockFilter==='low'?n(x.quantity)<=n(x.minimum):stockFilter==='available'?n(x.quantity)>0:!!x.discontinued));a.sort((x,y)=>{let v=z=>sort==='ral'?ral(z):sort==='works'?works(z):sort==='value'?n(z.price)*n(z.quantity):z[sort]??'';return (reverse?-1:1)*(typeof v(x)==='number'?v(x)-v(y):String(v(x)).localeCompare(String(v(y)),'pt-BR',{numeric:true}))});return a}
function mobileCards(items){
 return '<div class="stock-mobile-cards paint-mobile-cards" aria-label="Produtos do estoque de tintas">'+items.map(x=>{
  const swatch=colors[ral(x)]||(/^#[0-9a-fA-F]{6}$/.test(String(x.sheetColor||''))?x.sheetColor:'');
  const color=swatch?'<i class="stock-mobile-swatch" style="background:'+swatch+'" aria-hidden="true"></i>':'';
  const detail=(label,value)=>'<div><dt>'+label+'</dt><dd>'+escape(value??'—')+'</dd></div>';
  return '<article class="stock-mobile-card">'+
   '<div class="stock-mobile-heading"><div class="stock-mobile-title"><strong>'+escape(x.name)+'</strong><small>'+escape(x.id)+'</small></div>'+
   '<div class="stock-mobile-quantity"><small>Quantidade</small><strong>'+n(x.quantity).toLocaleString('pt-BR')+'</strong></div></div>'+
   '<div class="stock-mobile-summary"><span>'+color+' RAL <strong>'+escape(ral(x)||'—')+'</strong></span><span>Unit. <strong>'+amount(x.price)+'</strong></span></div>'+
   '<details class="stock-mobile-details"><summary>Mais detalhes</summary><dl>'+
    detail('Descrição',x.description)+detail('Valor em estoque',amount(n(x.price)*n(x.quantity)))+
    detail('Nível mínimo',n(x.minimum).toLocaleString('pt-BR'))+detail('Encomendar',Math.max(0,n(x.minimum)-n(x.quantity)).toLocaleString('pt-BR'))+
    detail('Obras',works(x)||'Nenhuma selecionada')+detail('Descontinuado',x.discontinued?'Sim':'Não')+
   '</dl></details><div class="stock-mobile-actions">'+
   '<button type="button" class="button secondary" data-paint-edit="'+escape(x.id)+'">Editar</button>'+
   '<button type="button" class="button secondary" data-paint-works="'+escape(x.id)+'">Obras</button>'+
   '</div></article>';
 }).join('')+(items.length?'':'<p class="stock-mobile-empty">Nenhum produto corresponde aos filtros.</p>')+'</div>';
}
function page(){let a=rows(),rals=[...new Set(list().map(ral).filter(Boolean))].sort(),worksList=[...new Set([...(state().projects||[]).map(x=>x.name),...list().flatMap(x=>x.works||[])])].filter(Boolean).sort();let headers=['ID','Nome','Descrição','Preço unitário','Qtd. estoque','Valor estoque','Nível estoque','Nome da obra','Qtd. encomendar','Descontinuado','RAL'];let html='<section class="page-head"><div><h1>Estoque de Tintas</h1><p class="subtitle">Separado do estoque Nextar · salvos no banco compartilhado</p></div><div class="actions"><button class="button primary" id="paintNew">+ Nova tinta</button><button class="button secondary" id="paintImport">Importar XLSX</button><button class="button secondary" id="paintExport">Exportar XLSX</button><input id="paintFile" type="file" accept=".xlsx" hidden></div></section>';html+='<div class="stats"><div class="stat"><div class="stat-label">Produtos</div><div class="stat-value">'+a.length+'</div></div><div class="stat"><div class="stat-label">Valor em estoque</div><div class="stat-value">'+amount(a.reduce((s,x)=>s+n(x.price)*n(x.quantity),0))+'</div></div></div>';html+='<div class="paint-controls"><input id="paintQ" placeholder="Buscar ID, nome, código, obra" value="'+escape(q)+'"><select id="paintRal"><option value="">Todos os RAL</option>'+rals.map(v=>'<option '+(v===ralFilter?'selected':'')+'>'+escape(v)+'</option>').join('')+'</select><select id="paintWork"><option value="">Todas as obras</option>'+worksList.map(v=>'<option '+(v===workFilter?'selected':'')+'>'+escape(v)+'</option>').join('')+'</select><select id="paintStock"><option value="">Todos</option><option value="available" '+(stockFilter==='available'?'selected':'')+'>Com estoque</option><option value="low" '+(stockFilter==='low'?'selected':'')+'>A encomendar</option><option value="discontinued" '+(stockFilter==='discontinued'?'selected':'')+'>Descontinuados</option></select><select id="paintSort">'+[['id','Código'],['name','Nome'],['description','Descrição'],['ral','RAL'],['price','Preço'],['quantity','Quantidade'],['value','Valor'],['minimum','Nível'],['works','Obras']].map(([k,v])=>'<option value="'+k+'" '+(sort===k?'selected':'')+'>'+v+'</option>').join('')+'</select><button id="paintOrder" class="button secondary">'+(reverse?'Decrescente ↓':'Crescente ↑')+'</button></div>';html+='<div class="paint-table"><table><thead><tr>'+headers.map(x=>'<th>'+x+'</th>').join('')+'<th>Ações</th></tr></thead><tbody>'+a.map(x=>'<tr><td>'+escape(x.id)+'</td><td>'+escape(x.name)+'</td><td>'+escape(x.description)+'</td><td>'+amount(x.price)+'</td><td>'+n(x.quantity)+'</td><td>'+amount(n(x.price)*n(x.quantity))+'</td><td>'+n(x.minimum)+'</td><td><button class="button secondary" data-paint-works="'+escape(x.id)+'">'+escape(works(x)||'Selecionar obras')+' ▾</button></td><td>'+Math.max(0,n(x.minimum)-n(x.quantity))+'</td><td>'+(x.discontinued?'Sim':'Não')+'</td><td>'+((colors[ral(x)]||x.sheetColor)?'<i class="paint-color" style="background:'+(colors[ral(x)]||x.sheetColor)+'"></i>':'')+escape(ral(x)||'—')+'</td><td><button class="button secondary" data-paint-edit="'+escape(x.id)+'">Editar</button></td></tr>').join('')+'</tbody></table></div>'+mobileCards(a)+'<p class="paint-note">Tons RAL em tela são aproximados; para fabricação, confirmar na carta física.</p><dialog id="paintDialog"><form id="paintForm" method="dialog"><h2 id="paintTitle"></h2><div id="paintFields"></div><div class="actions"><button class="button secondary" value="cancel">Cancelar</button><button class="button primary" value="save">Salvar</button></div></form></dialog>';return '<style>.paint-controls{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}.paint-controls input,.paint-controls select{padding:9px;border:1px solid #d2dae5;border-radius:7px}.paint-table{max-height:67vh;overflow:auto;border:1px solid #d2dae5;border-radius:9px}.paint-table table{min-width:1300px;width:100%;border-collapse:collapse}.paint-table th{position:sticky;top:0;background:#eaf0f7}.paint-table td,.paint-table th{padding:9px;border-bottom:1px solid #e0e6ee;text-align:left}.paint-color{display:inline-block;width:24px;height:24px;border:1px solid #aaa;border-radius:5px;vertical-align:middle;margin-right:6px}.paint-note{font-size:12px;color:#748194}#paintDialog{border:0;border-radius:14px;padding:24px;width:min(640px,96vw)}#paintFields label{display:block;margin:9px 0}#paintFields label input:not([type=checkbox]){width:100%;padding:9px}</style>'+html}
function save(rows){let next=root.Obras.clone(state()),all=new Map((next.paintStock||[]).map(x=>[x.id,x]));for(let x of rows)all.set(x.id,{...(all.get(x.id)||{}),...x});next.paintStock=[...all.values()];return Promise.resolve(root.EngefexPaintSave(next)).then(()=>{refresh();return next})}
function editor(id,workOnly){let x=list().find(x=>x.id===id)||{id:'',name:'',description:'',price:0,quantity:0,minimum:0,works:[],ral:'',discontinued:false},form=$('#paintForm');$('#paintTitle').textContent=workOnly?'Obras da tinta':'Cadastro de tinta';let html=workOnly?'':[['id','ID de estoque'],['name','Nome'],['description','Descrição'],['price','Preço unitário'],['quantity','Quantidade em estoque'],['minimum','Nível estoque'],['ral','RAL']].map(([k,v])=>'<label>'+v+'<input name="'+k+'" value="'+escape(x[k])+'" '+(id&&k==='id'?'readonly':'')+'></label>').join('')+'<label><input name="discontinued" type="checkbox" '+(x.discontinued?'checked':'')+'> Descontinuado</label>';let options=[...new Set([...(state().projects||[]).map(p=>p.name),...(x.works||[])])].filter(Boolean).sort();html+='<h3>Selecione uma ou várias obras</h3><div style="max-height:230px;overflow:auto">'+options.map(w=>'<label><input name="work" type="checkbox" value="'+escape(w)+'" '+((x.works||[]).includes(w)?'checked':'')+'> '+escape(w)+'</label>').join('')+'</div>';$('#paintFields').innerHTML=html;form.onsubmit=e=>{if(e.submitter?.value!=='save')return;let data=new FormData(form),item={...x,works:data.getAll('work')};if(!workOnly){for(let k of ['id','name','description','ral'])item[k]=String(data.get(k)||'').trim();for(let k of ['price','quantity','minimum'])item[k]=n(data.get(k));item.discontinued=!!data.get('discontinued');if(!item.id||!item.name||(!id&&list().some(y=>y.id===item.id))){e.preventDefault();alert('Confira ID e nome; IDs não podem se repetir.');return}}e.preventDefault();save([item]).then(()=>$('#paintDialog').close()).catch(err=>alert(err.message))};$('#paintDialog').showModal()}
async function importXLSX(file){const zip=await root.JSZip.loadAsync(file),str=async p=>zip.file(p)?zip.file(p).async('string'):'';let shared=new DOMParser().parseFromString(await str('xl/sharedStrings.xml'),'text/xml'),strings=[...shared.getElementsByTagName('si')].map(x=>x.textContent);let styleDoc=new DOMParser().parseFromString(await str('xl/styles.xml'),'text/xml'),fillNodes=[...styleDoc.getElementsByTagName('fills')[0]?.getElementsByTagName('fill')||[]],xfNodes=[...styleDoc.getElementsByTagName('cellXfs')[0]?.getElementsByTagName('xf')||[]];let fillByStyle=i=>{let f=fillNodes[Number(xfNodes[Number(i)]?.getAttribute('fillId')||0)],rgb=f?.getElementsByTagName('fgColor')[0]?.getAttribute('rgb')||'';return /^[0-9A-Fa-f]{8}$/.test(rgb)?'#'+rgb.slice(2):''};let doc=new DOMParser().parseFromString(await str('xl/worksheets/sheet1.xml'),'text/xml'),matrix=[...doc.getElementsByTagName('row')].map(row=>{let out={};for(let c of row.getElementsByTagName('c')){let col=c.getAttribute('r').match(/^[A-Z]+/)[0],v=c.getElementsByTagName('v')[0]?.textContent||'';out[col]=c.getAttribute('t')==='s'?strings[+v]||'':c.getAttribute('t')==='inlineStr'?c.getElementsByTagName('is')[0]?.textContent||'':v;if(col==='C')out.sheetColor=fillByStyle(c.getAttribute('s'))}return out});let idx=matrix.findIndex(x=>x.B==='ID de estoque');if(idx<0)throw Error('Cabeçalho ID de estoque não encontrado.');let rows=matrix.slice(idx+1).filter(x=>/^IN\d+/i.test(x.B||'')).map(x=>({id:x.B,name:x.C||'',description:x.D||'',price:n(x.E),quantity:n(x.F),minimum:n(x.H),works:(x.I||'').split(/[;,]/).map(w=>w.trim()).filter(Boolean),discontinued:/^(sim|true|1)$/i.test(x.K||''),sheetColor:x.sheetColor||'',ral:x.L||((x.C||'').match(/\bRAL\s*(\d{4})/i)||[])[1]||''}));if(!rows.length)throw Error('Sem linhas válidas.');if(confirm('Atualizar '+rows.length+' itens pelo ID? Itens ausentes serão preservados.'))await save(rows)}
async function exportXLSX(){let zip=new root.JSZip(),headers=['Para reordenar','ID de estoque','Nome','Descrição','Preço unitário','Quantidade em estoque','Valor de estoque','Nível de estoque','Nome da obra','Quantidade a encomendar','Descontinuado?','RAL'],cell=(k,v,r)=>'<c r="'+String.fromCharCode(65+k)+r+'" t="inlineStr"><is><t>'+escape(v)+'</t></is></c>',rows=[headers,...list().map(x=>['',x.id,x.name,x.description,x.price,x.quantity,n(x.price)*n(x.quantity),x.minimum,works(x),Math.max(0,n(x.minimum)-n(x.quantity)),x.discontinued?'Sim':'Não',ral(x)])];zip.file('[Content_Types].xml','<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>');zip.file('_rels/.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');zip.file('xl/workbook.xml','<?xml version="1.0"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Lista de estoque" sheetId="1" r:id="rId1"/></sheets></workbook>');zip.file('xl/_rels/workbook.xml.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>');zip.file('xl/worksheets/sheet1.xml','<?xml version="1.0"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>'+rows.map((v,i)=>'<row r="'+(i+3)+'">'+v.map((c,j)=>cell(j,c,i+3)).join('')+'</row>').join('')+'</sheetData></worksheet>');let blob=await zip.generateAsync({type:'blob'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Estoque de Tintas Engefex.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),20000)}
function bind(){for(let [id,fn] of [['paintRal',v=>ralFilter=v],['paintWork',v=>workFilter=v],['paintStock',v=>stockFilter=v],['paintSort',v=>sort=v]])$('#'+id)?.addEventListener('change',e=>{fn(e.target.value);refresh()});$('#paintQ')?.addEventListener('change',e=>{q=e.target.value;refresh()});$('#paintOrder')?.addEventListener('click',()=>{reverse=!reverse;refresh()});$('#paintNew')?.addEventListener('click',()=>editor());document.querySelectorAll('[data-paint-edit]').forEach(el=>el.onclick=()=>editor(el.dataset.paintEdit));document.querySelectorAll('[data-paint-works]').forEach(el=>el.onclick=()=>editor(el.dataset.paintWorks,true));$('#paintImport')?.addEventListener('click',()=>$('#paintFile').click());$('#paintFile')?.addEventListener('change',async e=>{try{if(e.target.files[0])await importXLSX(e.target.files[0])}catch(err){alert('Erro ao importar: '+err.message)}});$('#paintExport')?.addEventListener('click',()=>exportXLSX().catch(e=>alert(e.message)))}
root.EngefexPaints={page,bind};
})(window);